OUT=ROOT/'geometry-course/textbook/data/vector-chapter-review.json'


def question(n, title, task, result, hint, reasons, views, probes, theory, part=None):
    page=243 if n<=5 else 244
    stages=[(label,explanation,reason) for label,explanation,reason in reasons]
    entry=make(n,kind='exercise',part=part,pages=[page],title=title,statement=task,result=result,hint=hint,
               stages=stages,picture=diagram([views[0],*views],views),
               checks=[None,check(*probes[0]),check(*probes[1])])
    entry['id']=f'atanasyan-7-9-selfcheck-chapter-10-{n}-part-'+('2' if part=='б' else '1')
    entry['source']['collection']='selfcheck'
    entry['help'][1].update(text='Открой указанный пункт и проследи построение на его модели.',
                            theoryIds=[f'atanasyan-7-9-theory-{k}-part-1' for k in theory])
    entry['answer']['prompt']='Сначала запиши своё объяснение. Затем проверь его на другом примере.'
    entry['review']={**entry['review'],'reviewer':'Печатные с. 243–244, Атанасян, 14-е переработанное издание 2023 года. Содержание каждого вопроса и его подпунктов проверено по книге; новые примеры проверены по координатам.'}
    entry['visualization']['caption']='Сегмент UV задаёт единицу длины. Выбери рисунок, относящийся к своему шагу.'
    return entry


